from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts
    that are divisible by k.

    Args:
        low: Inclusive lower bound, 0 < low <= high <= 10**9.
        high: Inclusive upper bound.
        k: Divisor, 0 < k <= 20.

    >>> count_beautiful_integers(10, 20, 3)
    3
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        size = len(digits)

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int,
               started: bool, tight: bool) -> int:
            if pos == size:
                return int(started and balance == 0 and remainder == 0)
            # Each remaining digit can change the balance by only one.
            if abs(balance) > size - pos:
                return 0
            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    total += dp(pos + 1, 0, 0, False, next_tight)
                else:
                    total += dp(
                        pos + 1,
                        balance + (1 if digit % 2 == 0 else -1),
                        (remainder * 10 + digit) % k,
                        True,
                        next_tight,
                    )
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions modulo 998244353.

    Adjacent edge-sharing cells must contain different digits. The grid has
    H rows, W columns, and at most 200 cells; '?' denotes an unspecified cell.
    """
    mod = 998244353
    # Sweep along the longer dimension so the frontier has at most 14 cells.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit slot stores a frontier colour, with zero for cells outside
    # the grid. The oldest slot is directly above the current cell.
    mask = (1 << (2 * W)) - 1
    above_shift = 2 * (W - 1)
    dp = {0: 1}
    for row in grid:
        for col, cell in enumerate(row):
            choices = (1, 2, 3) if cell == "?" else (int(cell),)
            next_dp = {}
            for state, count in dp.items():
                above = (state >> above_shift) & 3
                left = (state & 3) if col else 0
                shifted = (state << 2) & mask
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = shifted | colour
                        next_dp[new_state] = (
                            next_dp.get(new_state, 0) + count
                        ) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, needed: int) -> int:
    """Count nonzero-digit suffixes with a given sum and product divisor."""
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _count_up_to(limit: int) -> int:
    if limit <= 0:
        return 0
    digits = [int(char) for char in str(limit)]
    length = len(digits)

    # Every positive number containing a zero is beautiful. Count its
    # complement, and collect the disjoint prefixes for nonzero numbers.
    nonzero_count = sum(9 ** size for size in range(1, length))
    branches = [(size, 0, 1) for size in range(1, length)]
    prefix_sum, prefix_product = 0, 1
    for index, digit in enumerate(digits):
        remaining = length - index - 1
        for smaller in range(1, digit):
            nonzero_count += 9 ** remaining
            branches.append((remaining, prefix_sum + smaller, prefix_product * smaller))
        if digit == 0:
            break
        prefix_sum += digit
        prefix_product *= digit
    else:
        nonzero_count += 1
        branches.append((0, prefix_sum, prefix_product))

    beautiful = limit - nonzero_count
    for remaining, prefix_sum, prefix_product in branches:
        for total in range(prefix_sum + remaining, prefix_sum + 9 * remaining + 1):
            if total == 0:
                continue
            # A nonzero digit product has only these four prime factors.
            residual = total
            for prime in (2, 3, 5, 7):
                while residual % prime == 0:
                    residual //= prime
            if residual != 1:
                continue
            needed = total // gcd(total, prefix_product)
            beautiful += _suffix_count(remaining, total - prefix_sum, needed)
    return beautiful


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

