from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count the number of integers x such that num1 <= x <= num2 and 
    min_sum <= digit_sum(x) <= max_sum, where digit_sum(x) is the sum of digits of x.

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    Returns:
        The number of good integers modulo 10^9 + 7

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def count(position: int, digit_sum: int, tight: bool) -> int:
            if digit_sum > max_sum:
                return 0
            if digit_sum + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= digit_sum <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                count(position + 1, digit_sum + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return count(0, 0, True)

    # Both prefix counts include their bounds, so restore the lower bound.
    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions modulo 998244353.

    Adjacent edge-sharing cells must contain different digits. The grid has
    H rows, W columns, and at most 200 cells; '?' denotes an unspecified cell.
    """
    mod = 998244353
    # Sweep along the longer dimension so the frontier has at most 14 cells.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit slot stores a frontier colour, with zero for cells outside
    # the grid. The oldest slot is directly above the current cell.
    mask = (1 << (2 * W)) - 1
    above_shift = 2 * (W - 1)
    dp = {0: 1}
    for row in grid:
        for col, cell in enumerate(row):
            choices = (1, 2, 3) if cell == "?" else (int(cell),)
            next_dp = {}
            for state, count in dp.items():
                above = (state >> above_shift) & 3
                left = (state & 3) if col else 0
                shifted = (state << 2) & mask
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = shifted | colour
                        next_dp[new_state] = (
                            next_dp.get(new_state, 0) + count
                        ) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

