    mod = 998244353
    positions = {}
    for i, c in enumerate(s):
        positions[c] = positions.get(c, 0) | (1 << i)
    transitions = []
    for state in range(1 << n):
        row = []
        for match in positions.values():
            x = state | match
            row.append(x & ~(x - ((state << 1) | 1)))
        transitions.append(row)
    absent = 26 - len(positions)
    dp = [0] * (1 << n)
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * (1 << n)
        for state, count in enumerate(dp):
            if not count:
                continue
            nxt[state] = (nxt[state] + count * absent) % mod
            for target in transitions[state]:
                nxt[target] = (nxt[target] + count) % mod
        dp = nxt
    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] = (answer[state.bit_count()] + count) % mod
    return answer

