from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    mod = 998244353
    masks = [0] * 26
    for i, ch in enumerate(s):
        masks[ord(ch) - ord('a')] |= 1 << i
    frequencies = {}
    for mask in masks:
        frequencies[mask] = frequencies.get(mask, 0) + 1
    transitions = []
    for state in range(1 << n):
        row = []
        for mask, frequency in frequencies.items():
            x = state | mask
            following = x & ~(x - ((state << 1) | 1))
            row.append((following, frequency))
        transitions.append(row)
    dp = [0] * (1 << n)
    dp[0] = 1
    for _ in range(m):
        following = [0] * (1 << n)
        for state, count in enumerate(dp):
            if count:
                for target, frequency in transitions[state]:
                    following[target] = (following[target] + count * frequency) % mod
        dp = following
    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + count) % mod
    return answer

