from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize a nonempty subsequence's bounded product at alternating sum k."""
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    overflow = limit + 1
    # All products above the limit are equivalent: only a later zero can
    # bring them back within the limit. Keep that state instead of dropping it.
    even = {}
    odd = {}
    for value in nums:
        next_even = even.copy()
        next_odd = odd.copy()
        for product, sums in even.items():
            new_product = min(overflow, product * value)
            next_odd[new_product] = next_odd.get(new_product, 0) | (sums << value)
        for product, sums in odd.items():
            new_product = min(overflow, product * value)
            next_even[new_product] = next_even.get(new_product, 0) | (sums >> value)
        # Explicit singletons ensure the empty subsequence is never accepted.
        singleton = min(overflow, value)
        next_odd[singleton] = next_odd.get(singleton, 0) | (1 << (bound + value))
        even, odd = next_even, next_odd
    target = 1 << (bound + k)
    answer = -1
    for states in (even, odd):
        for product, sums in states.items():
            if product <= limit and sums & target:
                answer = max(answer, product)
    return answer

