from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize a nonempty subsequence's bounded product at alternating sum k."""
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    overflow = limit + 1
    even = {}
    odd = {}
    for value in nums:
        next_even = even.copy()
        next_odd = odd.copy()
        for product, sums in even.items():
            following = min(overflow, product * value)
            next_odd[following] = next_odd.get(following, 0) | (sums << value)
        for product, sums in odd.items():
            following = min(overflow, product * value)
            next_even[following] = next_even.get(following, 0) | (sums >> value)
        product = min(overflow, value)
        next_odd[product] = next_odd.get(product, 0) | (1 << (bound + value))
        even, odd = next_even, next_odd

    target = 1 << (bound + k)
    products = even.keys() | odd.keys()
    return max(
        (product for product in products
         if product <= limit
         and (even.get(product, 0) | odd.get(product, 0)) & target),
        default=-1,
    )

