from typing import List
from collections import Counter

def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by LCS length with s, modulo 998244353."""
    mod = 998244353
    chars = {}
    for i, c in enumerate(s):
        chars[c] = chars.get(c, 0) | (1 << i)
    groups = [(mask, 1) for mask in chars.values()]
    if len(chars) < 26:
        groups.append((0, 26 - len(chars)))
    transitions = []
    for state in range(1 << n):
        counts = Counter()
        for mask, multiplicity in groups:
            x = state | mask
            counts[x & ~(x - ((state << 1) | 1))] += multiplicity
        transitions.append(list(counts.items()))
    dp = [0] * (1 << n)
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * len(dp)
        for state, count in enumerate(dp):
            if count:
                for dest, multiplicity in transitions[state]:
                    nxt[dest] = (nxt[dest] + count * multiplicity) % mod
        dp = nxt
    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + count) % mod
    return answer

