from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    full = (1 << (2 * bound + 1)) - 1
    cap = limit + 1
    dp = {}
    for value in nums:
        nxt = dp.copy()
        for product, (even, odd) in dp.items():
            q = min(cap, product * value)
            a, b = nxt.get(q, (0, 0))
            nxt[q] = (a | (odd >> value), b | ((even << value) & full))
        q = min(cap, value)
        a, b = nxt.get(q, (0, 0))
