from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s."""
    mod = 998244353
    matches = {}
    for i, character in enumerate(s):
        matches[character] = matches.get(character, 0) | (1 << i)
    groups = [(value, 1) for value in matches.values()]
    groups.append((0, 26 - len(matches)))
    size = 1 << n
    transitions = []
    for state in range(size):
        row = []
        for match, multiplicity in groups:
            x = state | match
            target = x & ~(x - ((state << 1) | 1))
            if multiplicity:
                row.append((target, multiplicity))
        transitions.append(row)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for target, multiplicity in transitions[state]:
                    following[target] = (following[target] + ways * multiplicity) % mod
        dp = following
    answer = [0] * (n + 1)
    for state, ways in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + ways) % mod
    return answer

