from typing import List

def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    mod = 998244353
    letter_masks = [0] * 26
    for i, c in enumerate(s):
        letter_masks[ord(c)-97] |= 1 << i
    size = 1 << n
    transitions = []
    for state in range(size):
        grouped = {}
        for letters in letter_masks:
            x = state | letters
            target = x & ~(x - ((state << 1) | 1)) & (size - 1)
            grouped[target] = grouped.get(target, 0) + 1
        transitions.append(list(grouped.items()))
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    nxt[target] += count * multiplicity
        dp = [v % mod for v in nxt]
    answer = [0] * (n+1)
    for state, count in enumerate(dp):
        answer[state.bit_count()] += count
    return [v % mod for v in answer]

