from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s."""
    mod = 998244353
    masks = {}
    for j, c in enumerate(s):
        masks[c] = masks.get(c, 0) | (1 << j)
    letters = [(mask, 1) for mask in masks.values()]
    if len(masks) < 26:
        letters.append((0, 26 - len(masks)))
    size = 1 << n
    transitions = []
    for state in range(size):
        destinations = {}
        for mask, multiplicity in letters:
            x = state | mask
            y = (state << 1) | 1
            nxt = x & ~(x - y)
            destinations[nxt] = destinations.get(nxt, 0) + multiplicity
        transitions.append(tuple(destinations.items()))
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for nxt, multiplicity in transitions[state]:
                    following[nxt] = (following[nxt] + ways * multiplicity) % mod
        dp = following
    answer = [0] * (n + 1)
    for state, ways in enumerate(dp):
        k = state.bit_count()
        answer[k] = (answer[k] + ways) % mod
    return answer

