from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize an admissible nonempty subsequence product."""
    offset = 12 * len(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    # product -> (even-length sum bitset, odd-length sum bitset).
    # All positive overflow products are equivalent; zero resets them.
    dp = {}
    for value in nums:
        additions = {}
        for product, (even, odd) in dp.items():
            dest = min(product * value, overflow)
            old_even, old_odd = additions.get(dest, (0, 0))
            additions[dest] = (old_even | (odd >> value),
                               old_odd | (even << value))
        dest = min(value, overflow)
        even, odd = additions.get(dest, (0, 0))
        additions[dest] = (even, odd | (1 << (offset + value)))
        for product, (even, odd) in additions.items():
            old_even, old_odd = dp.get(product, (0, 0))
            dp[product] = (old_even | even, old_odd | odd)
    target = 1 << (offset + k)
    return max((product for product, (even, odd) in dp.items()
                if product <= limit and (even | odd) & target),
               default=-1)

