def max_product_subsequence(nums, k, limit):
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    # Each pair stores bits for even-length, odd-length NONEMPTY subsequences.
    states = {}
    for a in nums:
        updated = dict(states)
        for product, (even, odd) in states.items():
            np = 0 if a == 0 else min(limit + 1, product * a)
            old_even, old_odd = updated.get(np, (0, 0))
            updated[np] = (old_even | (odd >> a), old_odd | (even << a))
        product = min(limit + 1, a)
        even, odd = updated.get(product, (0, 0))
        updated[product] = (even, odd | (1 << (bound + a)))
        states = updated
    target = 1 << (bound + k)
    answer = -1
    for product, (even, odd) in states.items():
        if product <= limit and (even | odd) & target:
            answer = max(answer, product)
