from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    even = {}
    odd = {}
    for value in nums:
        next_even = even.copy()
        next_odd = odd.copy()
        for product, sums in even.items():
            dest = min(overflow, product * value)
            next_odd[dest] = next_odd.get(dest, 0) | (sums << value)
        for product, sums in odd.items():
            dest = min(overflow, product * value)
            next_even[dest] = next_even.get(dest, 0) | (sums >> value)
        dest = min(overflow, value)
        next_odd[dest] = next_odd.get(dest, 0) | (1 << (offset + value))
        even, odd = next_even, next_odd
    target = 1 << (offset + k)
    return max((p for p in even.keys() | odd.keys()
                if p <= limit and ((even.get(p, 0) | odd.get(p, 0)) & target)),
               default=-1)
```
