from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count lowercase length-m strings by their LCS length with s."""
    mod = 998244353
    size = 1 << n
    matches = {}
    for i, char in enumerate(s):
        matches[char] = matches.get(char, 0) | (1 << i)
    # Equal letter masks have the same transition; absent letters stay put.
    letter_masks = [(mask, 1) for mask in matches.values()]
    if len(matches) < 26:
        letter_masks.append((0, 26 - len(matches)))
    transitions = []
    for state in range(size):
        row = []
        for match, multiplicity in letter_masks:
            x = state | match
            y = (state << 1) | 1
            row.append((x & ~(x - y) & (size - 1), multiplicity))
        transitions.append(row)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for target, multiplicity in transitions[state]:
                    following[target] = (following[target] + ways * multiplicity) % mod
        dp = following
    result = [0] * (n + 1)
    for state, ways in enumerate(dp):
        count = state.bit_count()
        result[count] = (result[count] + ways) % mod
    return result
