from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize a nonempty subsequence product <= limit with alternating sum k."""
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    odd, even = {}, {}
    for x in nums:
        next_odd, next_even = odd.copy(), even.copy()
        singleton = min(overflow, x)
        next_odd[singleton] = next_odd.get(singleton, 0) | (1 << (offset + x))
        for product, sums in even.items():
            dest = min(overflow, product * x)
            next_odd[dest] = next_odd.get(dest, 0) | (sums << x)
        for product, sums in odd.items():
            dest = min(overflow, product * x)
            next_even[dest] = next_even.get(dest, 0) | (sums >> x)
        odd, even = next_odd, next_even
    target = 1 << (offset + k)
    answer = -1
    for states in (odd, even):
        for product, sums in states.items():
            if product <= limit and sums & target:
                answer = max(answer, product)
    return answer

